import math
from sympy import primefactors

def get_divisors(n):
    return len(primefactors(n))

def min_operations(t, pairs):
    results = []
    for a, b in pairs:
        d1 = get_divisors(a)
        d2 = get_divisors(b)
        i = 0

        # Perform multiplication if needed
        if d1 < d2:
            while d1 < d2:
                if d2 % primefactors(b)[i] != 0:
                    d2 //= primefactors(b)[-1]
                    i -= 1
                else:
                    d2 //= primefactors(b)[-1]
                i += 1
            # Increase divisor count by the number of non-prime divisors of b
            # (the last element in primefactors(b) can be a combination of primes, not necessarily a prime itself)
            results.append(i + d2)
        elif d1 > d2:
            while d1 > d2:
                if d1 % primefactors(a)[i] != 0:
                    d1 //= primefactors(a)[-1]
                    i -= 1
                else:
                    d1 //= primefactors(a)[-1]
                i += 1
            results.append(i + d1)
        else:
            results.append(0)
    return results

# Example usage
