import sys

def find_original_array(B):
    N = len(B)
    sum_a = sum(B) - B[0]
    for i in range(N):
        if B[i] <= sum_a:
            B[i+1] -= B[i]
            B[i] = 0
            sum_a -= B[i]
    A = [0] * (N+1)
    A[1] = sum_a // 2
    for i in range(2, N+1):
        if sum_a > 0 and A[i-1] < sum_a:
            A[i] = A[i-1] + 1
            sum_a -= A[i]
        elif sum_a < 0 and A[i-1] > 0:
            A[i] = A[i-1] - 1
            sum_a += A[i]
        elif sum_a < 0:
            A[i] = 0
            if sum_a >= -A[i-1]:
                sum_a += -A[i-1]
            else:
                break
        elif sum_a > 0:
            A[i] = 1
            if sum_a > A[i-1]:
                sum_a -= A[i-1]
    if B[0] == 0 or not (sum_a == 0 and all(A[i] == A[-1] for i in range(1, N)) == True):
        return "NO"
    return "YES\n" + "\n".join(map(str, A))

# Example usage
if __name__ == "__main__":
    input=sys.stdin.readline
    N=int(input())
    B=list(map(int, input().strip().split(' ')))
    print(find_original_array(B))
