import math

def solve(n, edges):
    paths = []
    root = 1
    roots = [root]

    for i in range(1, n):
        if i in roots:
            paths.append((len(edges) - i, [i] + edges[i]))
            break
        cur_root = None
        for index, edge in enumerate(edges):
            if edge[1] in roots or edge[1] == i:
                if cur_root is None:
                    cur_root = i
                if cur_root != edge[0]:
                    paths.append((len(edges) - i, [index + 1] + edges[i][1:] + [index + 2] + edges[edge[0] - 1 + index+2]))
                    break
        if cur_root is None:
            cur_root = i
        roots.append(cur_root)

    return paths

