from typing import List

def min_total_distance(n: int, m: int, k: int, photos: List[str]) -> int:
    edges = [[] for _ in range(n + m)]
    for photo in photos:
        for i in range(n):
            for j in range(m):
                if photo[i] != "x":
                    edges[i + j * m].append((photo[i], i, j, 4 * b.upper() - photo[i]))
    cost = {i: [float('inf')] * (k + 1) for i in range(n)}
    dist = [float('inf')] * (k + 1)
    s = [(0, 0, 0)]
    visited = set()
    visited.add(0)
    while s:
        c, f, t = heapq.heappop(s)
        if t == k:
            return c
        for n, i, j, c2 in nearest_edges(edges, f):
            if n < m:
                dist[n + 1] = min(dist[n + 1], c + c2 + cost[t + 1])
            for d in range(dist[t] + 1, min(k + 1, n + 1)):
                if (i, j, n, d) in visited:
                    continue
                heapq.heappush(s, (d + cost[d - 2], d, t + 1))
                visited.add((i, j, n, d))
            cost[n + 1][f] = min(cost[n + 1][f], dist[d])
    return 0

def nearest_edges(edges: List[List[tuple]], x: int) -> List[tuple]:
    j, dis = float('inf'), float('inf')
    for i in range(m):
        if edges[x][i][1] <= j <= edges[x][i][2] and (edges[x][i][1] <= j <= edges[x][i][2]):
            dis = min(dis, edges[x][i][3])
        if edges[x][i][1] <= j <= edges[x][i][3] and edges[x][i][3] - edges[x][i][2] < j < edges[x][i][4] - edges[x][i][1] and (edges[x][i][1] <= j <= edges[x][i][4] - edges[x][i][3]) and (edges[x][i][1] <= j <= edges[x][i][4]):
            j = edges[x][i][2]
            dis = edges[x][i][3]
        j, dis = inf, inf
    for i in range(x + 1, len(edges)):
        if edges[i][m - 1][1] <= dis <= edges[i][m - 1][3] and edges[i][m - 1][3] - edges[i][m - 1][2] < dis < edges[i][m - 1][4] - edges[i][m - 1][1]:
            return i - 4, i
    for i in range(len(edges[x])):
        if edges[x][i][4] < edges[x][i][3]:
            j, dis = edges[x][i], edges[x][i][3]
            for jnp in range(i + 1, len(edges)):
                for jnp2 in range(m):
                    if j[np, i + np2][1] <= edges[x][jnp][jnp2][3] <= j[np, i + np2][2]:
                        j += 1
                        dis = edges[x][jnp][jnp2][3]
            return j - 4, x
        else:
            return x - 4, i
    for i in range(x - 1, -1, -1):
        if edges[i][0][4] < edges[i][0][3]:
            j, dis = edges[i], edges[i][0][3]
            for jnp in range(i + 1, len(edges)):
