from heapq import heappush, heappop, nsmallest

def calculate_distances(start):
    n, m = len(start), len(start[0])
    distances = [[float('inf')] * m for _ in range(n)]

    def dfs(x, y, reference):
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        distances[x][y] = 0
        stack = [(1, x, y, reference[x][y])]
        pq = [(1, x, y, reference[x][y])]

        while stack:
            distance, x, y, curr = heappop(stack)
            if distances[x][y] < distance:
                continue
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if (0 <= nx < n and 0 <= ny < m and distances[nx][ny] > dist * distance):
                    hdist = dx * abs(ord(reference[nx][ny]) - ord(curr))
                    if distances[nx][ny] > dist * hdist:
                        distances[nx][ny] = hdist
                        heappush(queue, (hdist, nx, ny, curr))

        return distances

    queue = []
    for y in range(m):
        dfs(0, y, start)

    return nsmallest(divmod((n * m) // len(queue) + 1, 3), queue)[1] / ((n * m) // len(queue) + 1)

def solution(n, m, k, areas):
