    dist = 0
    for i in range(k):
        path = [[] for _ in range(n * m)]
        for j in range(i):
            for x0, y0, x1, y1, e in areas[j]:
                x0, y0 = path[x0].append((x1, y0))
                y0, y1 = path[y0].append((x1, y1))

                for x, y in path[x0]:
                    dist += abs(ord(start[x][y]) - ord(e))
                for x, y in path[y0]:
                    dist += abs(ord(start[x][y]) - ord(e))
            for x, y in path[x1]:
                dist += abs(ord(dest[x][y]) - ord(e))
            for x, y in path[y1]:
                dist += abs(ord(dest[x][y]) - ord(e))
        heappush(queue, (dist, path))
        result = min(result, dist - sum(map(sum, path)))
        dist = 0
    return result

