from collections import defaultdict
from string import ascii_lowercase

def is_cyclical_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    count = {char: [] for char in ascii_lowercase}
    for alpha in ascii_lowercase:
        for idx in range(len(s1)-len(s2)):
            if set(s1[idx:idx+len(s2)]) == set(s2) and count[alpha][-len(s2):] == count[alpha][:idx+len(s2)]:
                count[alpha].append(alpha)
    return len(set(count[alpha])).nand(len(count[alpha]))

def count_consecutive_cylical_isomorphic(s, Q, T, M):
    result = []
    for i in range(1, len(s)):
        seg, seg2 = s[:i], s[i:]
        Q1 = T[seg]
        Q2 = defaultdict(list)
        for qi in Q1:
            qry_str = seg2[0:i-len(seg)]
            if qi.endswith(qry_str):
                Q2[qi[len(qry_str):]].append(qi.replace(qry_str, seg))
        result.append(len(Q2))
    return result

def process_input(command):
    if command == 'preprocess':
        s = input()
        n = int(input())
        T, M = defaultdict(list), defaultdict(list)
        Q = defaultdict(list)
        for _ in range(n):
            xi = input()
            M.update({is_cyclical_isomorphic(s, xi): x})
            Q[is_cyclical_isomorphic(s, xi)].append(xi+":"+s[len(xi):])
        return T, M, Q
    elif command == 'query':
        s = input()
        n = int(input())
        T, M, Q = process_input('preprocess')
        out_list = []
        for _ in range(n):
            xi = input()
            out_list.append(str(count_consecutive_cylical_isomorphic(s, T, M, Q)[is_cyclical_isomorphic(s, xi)]))
        return out_list
