        u, v = parent[a], parent[b]
        if not u == v:
            if u < v:
                u, v = v, u
            g[a * n * n + b * n + w] = b * n + w
            g[b * n * n + a * n + w] = a * n + w
            if not u == x[u]:
                a_original, b_original = a, b
                a, b = u, v
                if x[u] * n < x[v] * n:
                    a, b = n - b, n - a
                    w = x[a_original] - x[b_original]
            if u < v:
                parent[v] = x[u]
            else:
                parent[u] = x[v]

    def calc(x: int, p: int) -> int:
        total = 0
        for w in range(n):
            if w == p:
                total += g[w * n * n + x * n + p]
            else:
                min_d = g[w * n * n + x * n + p] - g[w * n * n + p * x + w]
                min_d //= w - x
                total += min_d
        return total

    return max(calc(x[i], j) for i in range(n) for j in range(x[i], x[i + 1]))

