from collections import defaultdict

def find_minimum_signpost_sum(n):
    roads = defaultdict(list)
    for _ in range(n - 1):
        a, *perishabilities = map(int, input().split())
        for perishability in perishabilities:
            roads[a].append(perishability)

    min_sum = [0] * n
    min_sum[1] = 0  # This is the museum city

    def dfs(city, father):
        for new_perishability in roads[city]:
            if new_perishability != father:
                new_sum = min_sum[new_perishability - 1] + new_perishability
                if min_sum[new_city_index := min(new_sum, min_sum[city])] > new_sum:
                    min_sum[new_city_index] = new_sum
                    dfs(new_city_index, new_perishability)
                if father and min_sum[new_city_index] > new_sum + min_sum[father]:
                    min_sum[new_city_index] = new_sum + min_sum[father]
                    dfs(new_city_index, -father)

    for i in range(1, n):
        min_sum[i] = sum(roads[i])
        dfs(i, 0)

    return min_sum

