from collections import deque

def find_original_array(N, B):
    stack = deque([])
    for i, b in enumerate(B):
        stack.append((b, i))

    while len(stack) > 1:
        next_sum = stack.pop()
        previous_sum = stack.pop()
        stack.append((next_sum[0] + previous_sum[0], previous_sum[1]))

    if stack:
        A = stack.pop()
    else:
        A = None

    if A is None or len(stack) != (N + 1) // 2:
        return "NO"

    A = deque(A[1:])
    B = map(lambda i: A.popleft(), range(N))

    return "YES" + " " + " ".join(map(str, B))

