def find_prime_factors(n):
    factors = []
    d = 2
    while d*d <= n:
        while (n % d) == 0:
            factors.append(d)
            n = n // d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def count_divisors(n):
    factors = find_prime_factors(n)
    divisors = 1
    for factor in factors:
        divisors *= (factors.count(factor) + 1)
    return divisors
