from collections import defaultdict
from heapq import heappush, heappop

def dijkstra(n, cost_matrix):
    cost = [float('inf')]*n
    cost[0] = 0
    heap = [(0, 0)]
    for _ in range(n-1):
        cur_cost, u = heappop(heap)
        if cur_cost > cost[u]:
            continue
        for v, w in cost_matrix[u].items():
            new_cost = max(cost[u], w) - cur_cost
            if new_cost < cost[v]:
                cost[v] = new_cost
                heappush(heap, (new_cost, v))
    return cost[n-1]

def find_museum(n, cost_matrix):
    for city in range(1, n):
        min_cost = float('inf')
        visited = defaultdict(bool)
        for _ in range(n):
            city_costs = {c: dijkstra(n, {i: v for (i, v) in zip(range(n), cost_matrix[c])}) for (c, v) in cost_matrix.items()}
            for v, cost in city_costs.items():
                if not visited[v]:
                    visited[v] = True
                    min_cost = min(min_cost, cost + city_costs[city])
        yield min_cost

