import math
from itertools import combinations_with_replacement

def check_edge_lines(points, xy1, xy2):
    def on_line(x1, y1, x2, y2, p):
        return math.isclose(p[0] - x1, p[1] - y1, rel_tol=1e-9) or \
               math.isclose(p[0] - x2, p[1] - y2, rel_tol=1e-9)

    lines = []
    for i, j in combinations_with_replacement(points, 2):
        x1, y1 = i
        x2, y2 = j
        if on_line(xy1[0], xy1[1], xy2[0], xy2[1], i):
            lines.append((i, xy2))
        if on_line(xy1[0], xy1[1], xy2[0], xy2[1], j):
            lines.append((j, xy1))
        if on_line(xy1[0], xy1[1], i, j, (x1 + x2) / 2, (y1 + y2) / 2):
            lines.append((-1, [x1 + (x2 - x1) / 2, y1 + (y2 - y1) / 2]))
    return all(on_line(*l, xy1) or on_line(*l, xy2) for l in lines)

def minimum_r(points):
    ax, ay = min(points, key=lambda p: p[0])[0], min(points, key=lambda p: p[1])[1]
    bx, by = max(points, key=lambda p: p[0])[0], max(points, key=lambda p: p[1])[1]
    r = max(math.dist((0, 0), p) for p in points) + 1
    for r in range(1, 2*r):
        if any(check_edge_lines(points, (ax+r, by), (bx+r, ay)) or check_edge_lines(points, (ax-r, by), (bx-r, ay)) or check_edge_lines(points, (ax, by+r), (bx, by-r)) or check_edge_lines(points, (ax, by-r), (bx, by+r))):
            break
    return r

