from collections import defaultdict
from heapq import heappush, heappop

def dijkstra(graph, start):
    distances = defaultdict(lambda: float('inf'))
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_city = heappop(priority_queue)

        for neighbor, weight in graph[current_city]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def find_min_total_sum(graph):
    n = len(graph) + 1
    total_sum = 0
    frontier = [(0, node) for node in range(1, n)]

    while frontier:
        total_sum += -heappop(frontier)[0]
        for neighbor, weight in graph[frontier[0]][-1]:
            if frontier[0] != neighbor:
                heappush(frontier, (frontier[0] + weight, neighbor))

    return total_sum

