from fractions import Fraction

def calculate_average_danger(n, k, connections):
    row_sum = Fraction(0, k-1)
    even_sum = Fraction(0, 2)
    for i in range(1, n, 2):
        row_sum += connections[i][i//2]
        even_sum += connections[i][3-i//2]
    for i in range(2, n, 2):
        row_sum += connections[i][i//2]
        even_sum += connections[i][3-i//2]
    if n % 2 == 0:
        return int(2 * even_sum / (n-2))
    else:
        return int(3 * row_sum / (n-1))

