from math import factorial
from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    return fibonacci(n-1) + fibonacci(n-2)

@lru_cache(maxsize=None)
def catalan(n):
    if n == 0:
        return 1
    elif n == 1:
        return 0
    return factorial(2*n) // (factorial(n+1) * factorial(n))

