def _remove_overlapping_segments(segment_memory, global_memory):
    for start in segment_memory.keys():
        for end in segment_memory[start].keys():
            if end < start:
                continue
            start_memo, end_memo = global_memory[start+1][end-start+1], global_memory[end][end+1]
            if start_memo + end_memo > 0:
                global_memory[start_memo + end_memo+1] += start_memo * end_memo
                del segment_memory[start][end]

# Helper function for updating the global memory based on parent segments
def _update_global_parent_segment(memory, segment_memory):
    global memory
    updated_memory = {}
    start_memo = -1
    end_memo = -1

    for global_key in sorted(memory.keys()):
        global_val = memory[global_key]
        start_memo = end_memo
        end_memo = global_key
        if segment_memory[end_memo][end_memo+1] == 0:
            del segment_memory[end_memo+1]
            updated_memory[global_key] = (global_val * end_memo) + (segment_memory[start_memo][global_key] * start_memo)
