from collections import defaultdict, deque

def dijkstra(graph, start):
    distances = {city: float('infinity') for city in graph}
    distances[start] = 0
    visited = set()
    queue = deque([(0, start)])

    while queue:
        current_dist, current_city = queue.popleft()

        if current_city not in visited:
            visited.add(current_city)
            for neighbor, distance in graph[current_city].items():
                if current_dist + distance < distances[neighbor]:
                    distances[neighbor] = distance + current_dist
                    queue.append((distance + current_dist, neighbor))

    return distances

