def get_input_array_outputted(N: int, B: List[int]) -> List[int]:
    new_B = [0] * len(B)
    for i in range(N):
        for j in range(i, len(B)):
            new_B[j] += B[i]
    return new_B

def is_valid_input(A: List[int], B: List[int]) -> bool:
    seen = set()
    new_B = get_input_array_outputted(len(A), A)
    for i, b in enumerate(new_B):
        if b in seen:
            return False
        seen.add(b)
    for i in range(1, len(A)):
        if i + 1 not in seen:
            return False
    return True

def find_input_array(B: List[int]) -> List[int]:
    if not is_valid_input(B, B):
        return None
    for i in range(2, len(B) + 1):
        if is_valid_input(B, B[:i]):
